void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb_checksum_complete(skb)) {
        return;
    }

    if (offset > 0) {
        int partial_csum = skb_checksum(skb, tlen, offset, 0);
        skb->csum = csum_sub(skb->csum, partial_csum);
    }

    msg->msg_control = skb->csum;
}

void append_checksum_to_msg(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed || skb->ip_summed != CHECKSUM_COMPLETE) {
        return;
    }

    if (offset > 0) {
        skb->csum = csum_sub(skb->csum, csum_partial(skb->data + tlen, offset, 0));
    }

    msg->msg_control = skb->csum;
}

void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset)
{
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        skb->csum = csum_sub(skb->csum, skb_checksum(skb, tlen, offset, 0));
    }

    msg->msg_control = skb->data + tlen;
    msg->msg_controllen = skb->len - tlen;
}

void append_checksum_to_msg(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        __sum16 old_csum = skb_checksum(skb, tlen, offset, skb->data, skb->len - tlen);
        __sum16 new_csum = csum_tcpudp_nofold(msg->msg_name, skb->len - tlen, skb->len - tlen, IPPROTO_UDP, 0);
        new_csum = csum_add(new_csum, csum_sub(~old_csum, 0));
        msg->msg_flags |= new_csum;
    } else {
        __sum16 csum = csum_tcpudp_nofold(msg->msg_name, skb->len - tlen, skb->len - tlen, IPPROTO_UDP, 0);
        msg->msg_flags |= csum;
    }
}

void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        __sum16 partial_csum = skb_checksum(skb, tlen, skb->len - tlen - offset, NULL);
        csum_sub(skb->csum, partial_csum);
    }

    msg->msg_control = skb->csum;
}
